\begin{equation} \label{S1.def}
S_{Q,T,\lambda_0,\gamma_0}(t,x) = e^{i\gamma_0} e^{i\frac{\lambda_0^2}{T-t}} e^{-i\frac{|x|^2}{4(T-t)}}
