\label{minimization.prop}
 For $1<p<1+\frac{4}{N-2}$,
\[
\alpha_{p,N} := \inf_{u\in H^1(\mathbb{R}^N)\backslash\{0\}} J^{p,N}(u)
\]
is attained at a positive radial function $Q\in H^1(\mathbb{R}^N)$, solution of the Euler--Lagrange equation
\begin{equation}\label{EL}
N\Big(\frac{p-1}{4}\Big)\Big(\Delta Q +c\frac{Q}{|x|^2}\Big)-\left(1+\frac{p-1}{4}(2-N)\right)Q+Q^p=0.
\end{equation}
Furthermore,
\begin{equation} \label{sharpestimate}
\alpha_{p,N}=2\frac{\|Q\|_{L^2}^{p-1}}{p+1}.
\end{equation}
In the case $p=1+\frac4N$, any minimizer of $J^{p,N}$ can be rescaled into a solution of \eqref{sinls}.

\label{GN.cor} For $1<p<1+\frac{4}{N-2}$ and $u\in H^1(\mathbb{R}^N)$, we have
\begin{equation}\label{GN}
\Vert u\Vert_{L^{p+1}}^{p+1} \le 
\alpha_{p,N}^{-1} H(u)^{\frac{p-1}{4}N} \Vert u\Vert_{L^{2}}^{2+\frac{p-1}{2}(2-N)},
\end{equation}
where
\[
\alpha_{p,N}=\frac{M_\mathrm{gs}^{\frac{4}{N}}}{1+\frac{2}{N}}
\quad\text{in the critical case} \quad p=1+\frac{4}{N}. 
\]

\label{minmass.rem}
It follows from Lemma~\ref{pseudo-conf.lem} that any solution $\varphi$ of \eqref{sinls}
satisfies $\|\varphi\|_{L^2}\ge M_\mathrm{gs}$. Otherwise, applying Lemma~\ref{pseudo-conf.lem}
with $u(t,x)=e^{it}\varphi(x)$, one could construct a finite time blow-up solution below the minimal mass 
threshold, which would contradict our global well-posedness result, Theorem~\ref{global.thm}.

 \label{blow-up_sol.prop}
For all $Q\in\mathcal{G}$, $T\in\mathbb{R}$, $\lambda_0>0$ and $\gamma_0\in\mathbb{R}$, the function 
$S_{Q,T,\lambda_0,\gamma_0}$, defined by
\begin{equation} \label{S2.def}
S_{Q,T,\lambda_0,\gamma_0}(t,x) = e^{i\gamma_0} e^{i\frac{\lambda_0^2}{T-t}} e^{-i\frac{|x|^2}{4(T-t)}}
\left(\frac{\lambda_0}{T-t}\right)^{N/2}Q\left( \frac{\lambda_0x}{T-t} \right),
\end{equation}
is a minimal mass solution of~\eqref{inls} defined on $(-\infty,T)$, and which blows up with speed
\[
\Vert\nabla S_{Q,T,\lambda_0,\gamma_0}(t)\Vert_{L^2} \sim \frac{C}{T-t} \quad \text{as } t\to T,
\]
for some $C>0$.

\label{charact.prop}
Let $v\in H^1(\mathbb{R}^N)$ be such that 
\begin{equation} \label{varchar}
\|v\|_{L^2}=M_\mathrm{gs} \quad \text{and} \quad E(v)=0.
\end{equation}
Then there exist $Q\in\mathcal{G}$, and $\gamma_0 \in \mathbb{R}$ 
such that $v(x)=e^{i\gamma_0}\lambda_0^{N/2}Q(\lambda_0x)$,
where $\displaystyle\lambda_0=\sqrt{\frac{2}{N}}\frac{\sqrt{H(|v|)}}{M_\mathrm{gs}}$.

\label{compact.prop}
Consider a sequence $\{v_n\}_{n\in\mathbb{N}}\subset H^1(\mathbb{R}^N)$ satisfying
\begin{equation} \label{a}
\lim_{n\rightarrow\infty}\|v_n\|_{L^2}=M_\mathrm{gs}, \quad 0<\limsup_{n\in\mathbb{N}}H(v_n)<+\infty,
\quad \limsup_{n\rightarrow\infty}E(v_n)\le 0.
\end{equation}
Then there exists a subsequence $\{v_{n_k}\}_{k\in\mathbb{N}}$, $\gamma_0\in\mathbb{R}$ and $Q\in\mathcal{G}$ such that
\begin{equation}\label{compact}
\lim_{k\rightarrow\infty}\|v_{n_k}-e^{i\gamma_0}Q\|_{H^1}=0.
\end{equation}

Consider a sequence $\{v_n\}_{n\in\mathbb{N}}\subset H^1(\mathbb{R}^N)$ satisfying
\begin{equation} \label{a}
\lim_{n\rightarrow\infty}\|v_n\|_{L^2}=M_\mathrm{gs}, \quad 0<\limsup_{n\in\mathbb{N}}H(v_n)<+\infty,
\quad \limsup_{n\rightarrow\infty}E(v_n)\le 0.
\end{equation}
Then there exists a subsequence $\{v_{n_k}\}_{k\in\mathbb{N}}$, $\gamma_0\in\mathbb{R}$ and $Q\in\mathcal{G}$ such that
